import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output, SimpleChanges } from '@angular/core';
import { IssueService } from '../../../services/issues/issue.service';
import { issueList, selectedIssues } from '../../../interfaces/issue.interface';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatSelectModule } from '@angular/material/select';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { FormsModule } from '@angular/forms';
import { IconComponent } from '../../icon/icon.component';
import { CommonModule } from '@angular/common';
import { codeData } from '../../../interfaces/common.interface';
import { CommonService } from '../../../services/common/common.service';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { CreateissueComponent } from '../../../../realtime/components/issues/createissue/createissue.component';
import { MatDialog } from '@angular/material/dialog';

@Component({
  selector: 'choose-issue',
  changeDetection: ChangeDetectionStrategy.OnPush,
  standalone: true,
  imports: [CommonModule, MatFormFieldModule, MatSelectModule, MatCheckboxModule, FormsModule, IconComponent],
  templateUrl: './choose-issue.component.html',
  styleUrl: './choose-issue.component.scss'
})
export class ChooseIssueComponent implements OnInit {
  @Input() nCaseid: string;
  @Input() selectedIssues: selectedIssues[] = [];
  @Input() expandIssue = true;
  @Input() intoolbar = false;
  @Input() isfilter = false;
  @Output() OnDataRec = new EventEmitter<any>();
  @Output() Onevent = new EventEmitter<any>();


  issueList: issueList[] = [];
  isLoading: boolean = true;
  relevences: codeData[] = [];
  impacts: codeData[] = [];

  constructor(private issueService: IssueService, private commonService: CommonService, private cdr: ChangeDetectorRef, private cf: CommonfunctionService, private dialog: MatDialog) {

  }

  ngOnChanges(changes: SimpleChanges): void {

    if (changes['selectedIssues']) {    
      // this.cdr.detectChanges();
      this.handleSelectedIssues();
    }
  }

  ngAfterViewInit() {
    if (!this.nCaseid) return;
    this.issueService.fetchIssueList(this.nCaseid).then(res => {
      this.issueList = res;
      if (this.selectedIssues != null) {
        this.handleSelectedIssues();
        // this.issueList.forEach(item => {
        //   const Obj: selectedIssues = this.selectedIssues.find(a => (a.nIid || a.nIssueid) == item.nIid);
        //   if (Obj) {
        //     item.isChecked = true;
        //     item.nImpactid = Obj.nImpactid || 0;
        //     item.nRelid = (Obj.nRelid || Obj.nRelevanceid) || 0;
        //     item.nSerial = Obj.nSerial;
        //   }
        // })
      }
      this.isLoading = false;
      this.cdr.detectChanges();
      this.initList();
    });

  }

  async ngOnInit() {

  }


  async initList() {
    this.relevences = await this.commonService.getCode(4);
    this.impacts = await this.commonService.getCode(5);
    try {
      this.OnDataRec.emit({ issueList: this.issueList, relevences: this.relevences, impacts: this.impacts });
    } catch (error) {

    }
    this.cdr.detectChanges();
  }
  getCKey(nRelid: number, type): string {

    if (type == 'R') {
      const relevance = this.relevences.find(item => item.nValue == nRelid);
      return relevance ? relevance.cKey : 'Select...';
    } else {
      const impact = this.impacts.find(item => item.nValue == nRelid);
      return impact ? impact.cKey : 'Select...';
    }
  }

  saveIssue() {
    // const issueList: selectedIssues[] = this.issueList.filter(item => item.isChecked).map(a => ({ nIid: a.nIid, nImpactid: a.nImpactid, nRelid: a.nRelid }));
    // this.selectedIssues.splice(0, this.selectedIssues.length);
    // this.selectedIssues.push(...issueList);
  }
  findMaxValue(array, key) {
    try {
      // Check if the array is valid and not empty
      if (!array || array.length === 0) {
        return 0; // Return 0 for an empty array
      }
      // Filter objects that have the key and its value is numeric
      const filteredArray = array.filter(item => key in item && typeof item[key] === "number");

      // If no valid items with the key are found, return 0
      if (filteredArray.length === 0) {
        return 0;
      }
      // Use reduce to find the maximum value
      return filteredArray.reduce((max, item) => Math.max(max, item[key]), -Infinity);
    } catch (error) {
      return 0;
    }
  }

  onIssueChecked(x: issueList) {
    debugger;
    const maxid = this.findMaxValue(this.selectedIssues, 'nSerial');
    const ind = this.selectedIssues.findIndex(a => (a.nIid || a.nIssueid) == x.nIid);
    if (ind == -1) {
      if (x.isChecked) {
        this.selectedIssues.push({ cColor: x.cColor, cIName: x.cIName, nIid: x.nIid, nImpactid: x.nImpactid, nRelid: (x.nRelid || x.nRelevanceid), dt: this.cf.getCurrentTime(), nSerial: maxid + 1 });
      }
    } else {
      if (!x.isChecked) {
        this.selectedIssues.splice(ind, 1);
      }
    }
    this.Onevent.emit({ event: 'ISSUE_CHNAGE', data: this.selectedIssues });
    this.cdr.detectChanges();
  }


  UpdateRelavance(x) {
    const ind = this.selectedIssues.findIndex(a => (a.nIid || a.nIssueid) == x.nIid);
    if (ind != -1)
      this.selectedIssues[ind].nRelid = x.nRelid;
    this.Onevent.emit({ event: 'ISSUE_CHNAGE', data: this.selectedIssues });
    this.cdr.detectChanges();
  }

  UpdateImpace(x) {
    const ind = this.selectedIssues.findIndex(a => (a.nIid || a.nIssueid) == x.nIid);
    if (ind != -1)
      this.selectedIssues[ind].nImpactid = x.nImpactid;
    this.Onevent.emit({ event: 'ISSUE_CHNAGE', data: this.selectedIssues });
    this.cdr.detectChanges();
  }





  createIssue() {
    const dialog = this.dialog.open(CreateissueComponent, {
      width: '440px',
      height: 'calc(100% - 50px)',
      hasBackdrop: this.intoolbar ? true : false,
      backdropClass: this.intoolbar ? ['top-[50px]', 'bg-black/50'] : '',
      panelClass: ['noshadow', 'norounded'],
      position: {
        top: `50px`,
        right: `0px`,
      },
      data: { type: null, value: null, current_session: { nCaseid: this.nCaseid } },
    });
    dialog.afterClosed().subscribe((result) => {
      this.ngAfterViewInit();
      this.cdr.detectChanges();
    })
  }

  advance() {
    this.Onevent.emit({ event: 'ADVANCE', data: this.selectedIssues });
  }

  checkwidth(x) {
    let wth
    if (this.intoolbar) {
      wth = '28px'
      if (x.isChecked) {
        wth = '48px'
      }
      if (x.nImpactid) {

        wth = '78px'
      }
      if (x.nRelid) {
        wth = '120px'
      }
    }
    else {
      if (x.nRelid) {
        wth = '180px'
      }
    }
    return wth;

  }

  handleSelectedIssues() {
    if (this.selectedIssues == null || this.selectedIssues?.length == 0) {
      this.issueList.forEach(item => { item.isChecked = false });
      return;
    }
    this.issueList.forEach(item => {
      const Obj: selectedIssues = this.selectedIssues?.find(a => (a.nIid || a.nIssueid) == item.nIid);
      if (Obj) {
        item.isChecked = true;
        item.nImpactid = Obj.nImpactid || 0;
        item.nRelid = (Obj.nRelid || Obj.nRelevanceid) || 0;
        item.nSerial = Obj.nSerial;
      }else{
        item.isChecked = false;
        item.nImpactid = 0;
        item.nRelid =  0;
      }
    })
    this.cdr.detectChanges();
  }
}
